{"type": "post", "post": {"team": "store-operations", "channel": "labeling-efficiency", "user": "monica.tran", "message": "Hey team, just finished reviewing the Q2 monthly operational reviews. We need to talk about the labor hours going into shelf labels.", "create_at": 1689940800000}}
{"type": "post", "post": {"team": "store-operations", "channel": "labeling-efficiency", "user": "david.chen", "message": "Yeah I saw those numbers come through. What's the damage?", "create_at": 1689941100000}}
{"type": "post", "post": {"team": "store-operations", "channel": "labeling-efficiency", "user": "monica.tran", "message": "Manual shelf label changes are consuming approximately 95 staff hours on average per month across each location. The multilingual updates are the biggest time sink.", "create_at": 1689941400000}}
