{"type": "post", "post": {"team": "store-operations", "channel": "labeling-efficiency", "user": "monica.tran", "message": "I'll share the proposal draft by end of week. Let's schedule a call Monday to discuss implementation timelines.", "create_at": 1689943500000}}

