{"type": "post", "post": {"team": "it-operations", "channel": "service-desk-analytics", "user": "kevin.nguyen", "message": "Hey team, I've been looking at our service desk email patterns across all stores. Management wants to know if there are specific days or times when we see spikes.", "create_at": 1738252800000}}
