{"type": "post", "post": {"team": "digital-products", "channel": "chatbot-dev", "user": "kevin.tran", "message": "Great work everyone. Let's keep pushing. I'll update the exec team on our July 2027 target for full rollout.", "create_at": 1712508000000}}

