{"type": "post", "post": {"team": "sales", "channel": "centennial-outreach", "user": "marcus.chen", "message": "Hey team, wanted to check in on how our conversational AI rollout is going for Centennial shoppers. We're about a month into Q2 now.", "create_at": 1745942400000}}
