{"type": "email", "id": "email_003", "subject": "RE: Cybersecurity Awareness and Training Program Proposal", "from": "jason.wong@leesmarket.com", "from_name": "Jason Wong", "to": ["linda.lee@leesmarket.com"], "cc": ["michael.chen@leesmarket.com", "amy.liu@leesmarket.com"], "date": "2025-01-10 16:00:00", "body": "Linda,

