{"type": "user", "user": {"username": "marcus.williams", "email": "marcus.williams@leesmarket.com", "password": "SecurePass789!", "teams": [{"name": "it-security", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "jennifer.liu", "email": "jennifer.liu@leesmarket.com", "password": "SecurePass012!", "teams": [{"name": "it-security", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "david.chen", "message": "Team, just got the Q3 security assessment results back. We need to discuss some concerning findings about our vulnerability exposure.", "create_at": 1728640800000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "priya.sharma", "message": "What's the main concern? The phishing simulation results?", "create_at": 1728641100000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "david.chen", "message": "Exactly. HR shared their latest numbers - we're sitting at 45% annual staff turnover across our 5,000 employees. That means roughly 25% of our workforce at any given time has been here less than six months.", "create_at": 1728641400000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "marcus.williams", "message": "That's brutal for security awareness. New hires are always the weakest link for phishing and social engineering.", "create_at": 1728641700000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "jennifer.liu", "message": "I ran the numbers on our last phishing test - employees under 6 months clicked malicious links at 3x the rate of veteran staff. The gap is real.", "create_at": 1728642000000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "priya.sharma", "message": "With our expansion into more urban centers, the retail floor staff turnover is even higher. Those POS systems are prime targets.", "create_at": 1728642300000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "david.chen", "message": "We need to rethink our onboarding security training. Current 2-hour module isn't cutting it. Proposing mandatory monthly refreshers for the first year.", "create_at": 1728642600000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "marcus.williams", "message": "Agreed. Also suggesting we implement stricter email filtering for accounts under 90 days. Quarantine more aggressively.", "create_at": 1728642900000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "jennifer.liu", "message": "Good idea. I'll draft a proposal for leadership. This turnover issue creates persistent cybersecurity gaps we can't ignore.", "create_at": 1728643200000}}
{"type": "post", "post": {"team": "it-security", "channel": "cybersecurity-ops", "user": "david.chen", "message": "Let's sync tomorrow at 10am to finalize recommendations. We need budget approval before year-end.", "create_at": 1728643500000}}

