{"type": "user", "user": {"username": "kevin.nguyen", "email": "kevin.nguyen@leesmarket.com", "password": "SecurePass789!", "roles": "system_user", "teams": [{"name": "security-ops", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "lisa.park", "email": "lisa.park@leesmarket.com", "password": "SecurePass321!", "roles": "system_user", "teams": [{"name": "security-ops", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "michelle.torres", "message": "Hey team, we need to discuss our security posture for the dual-channel expansion. Moving into Q1 2026, this is becoming a real concern.", "create_at": 1708768800000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "derek.chang", "message": "Agreed. I've been reviewing some industry reports and I think around 42% of previous retail breaches might have involved compromised POS or e-commerce endpoints. Pretty alarming stuff.", "create_at": 1708769100000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "kevin.nguyen", "message": "That's a big number. So moving into Q3 2026, our employees at Lee's Market could be managing security at both digital and physical checkout points simultaneously? That's a lot to handle.", "create_at": 1708769400000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "lisa.park", "message": "Yeah, I'm pretty sure that's the main challenge with dual-channel retail. In-store POS systems and online checkout are both vulnerable attack surfaces.", "create_at": 1708769700000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "michelle.torres", "message": "Exactly. With our expansion across urban centers in the U.S. and Canada, we're essentially doubling our exposure. Each new location means more endpoints to secure.", "create_at": 1708770000000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "derek.chang", "message": "The online grocery delivery service is growing fast too. I think that might be where we see the most risk, since e-commerce platforms are constantly targeted.", "create_at": 1708770300000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "kevin.nguyen", "message": "Should we propose additional training for store managers? They need to understand both physical POS vulnerabilities and digital threats.", "create_at": 1708770600000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "lisa.park", "message": "Good idea. I'll draft a proposal. With 5000 employees across all locations, consistent security awareness could really reduce our risk profile.", "create_at": 1708770900000}}
{"type": "post", "post": {"team": "security-ops", "channel": "retail-security-q1", "user": "michelle.torres", "message": "Thanks Lisa. Let's sync tomorrow and finalize our Q1 recommendations. This dual-channel challenge isn't going away.", "create_at": 1708771200000}}

