{"type": "post", "post": {"team": "operations", "channel": "it-security", "user": "jennifer.liu", "message": "Team, I need everyone's attention. Following our Q4 2023 incident review, we need to discuss our cybersecurity posture going forward.", "create_at": 1722765600000}}
{"type": "post", "post": {"team": "operations", "channel": "it-security", "user": "david.wong", "message": "Absolutely Jennifer. I've compiled the full impact analysis from the Q4 2023 cyberattacks. The numbers are sobering.", "create_at": 1722765900000}}
