{"type": "user", "user": {"username": "lisa.nguyen", "email": "lisa.nguyen@mediconn.ca", "password": "PharmConnect#25", "teams": [{"name": "operations", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "daniel.cho", "message": "Hey team, I've been getting questions from corporate clients about our current prescription timelines. Can someone give me a quick summary of where we stand?", "create_at": 1732358400000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "priya.sharma", "message": "Sure Daniel! Our electronic prescriptions are sent to partner pharmacies within 30 minutes of the virtual visit concluding. The integration we rolled out in early 2025 has been working really smoothly.", "create_at": 1732358520000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "marcus.bell", "message": "And for delivery options:\n\n| Option | Timeline | Cost |\n|--------|----------|------|\n| Same-day delivery (metro areas) | Same day | $8 |\n| Standard delivery | 12-24 hours | Varies |\n| Pharmacy pickup | Within 4 hours | Free |", "create_at": 1732358700000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "lisa.nguyen", "message": "The pharmacy pickup option at participating locations has been really popular. Patients love the free option and the 4-hour turnaround is competitive.", "create_at": 1732358820000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "daniel.cho", "message": "This is great! Are we expecting any changes to these timelines going into 2026?", "create_at": 1732358940000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "priya.sharma", "message": "No major changes planned. Leadership confirmed these improvements are expected to continue through 2026. We might see expanded same-day delivery coverage to smaller cities, but core timelines stay the same.", "create_at": 1732359120000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "marcus.bell", "message": "The $8 reduced fee for same-day has driven a lot of adoption in Toronto and Vancouver. Really happy with how this has worked out since the early 2025 rollout \ud83d\udc4d", "create_at": 1732359300000}}
{"type": "post", "post": {"team": "operations", "channel": "prescription-services", "user": "daniel.cho", "message": "Perfect, thanks everyone! I'll update our client FAQ with these details.", "create_at": 1732359420000}}

