{"type": "post", "post": {"team": "patient-support", "channel": "booking-ops", "user": "rachel.chen", "message": "Hey team, just pulled together our Q3 and Q4 booking ticket resolution metrics. Wanted to share before the holiday break.", "create_at": 1703498400000}}
