{"type": "post", "post": {"team": "client-success", "channel": "retention-strategies", "user": "priya.sharma", "message": "Hey team, quick question - does anyone have details on the retention playbook we rolled out earlier this year? Leadership wants a summary for the year-end review.", "create_at": 1735041600000}}
