{"type": "user", "user": {"username": "daniel.chen", "email": "daniel.chen@mediconn.ca", "password": "SecurePass123!", "teams": [{"name": "strategy", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "priya.sharma", "email": "priya.sharma@mediconn.ca", "password": "SecurePass456!", "teams": [{"name": "strategy", "roles": "team_user team_admin"}]}}
{"type": "user", "user": {"username": "marcus.wright", "email": "marcus.wright@mediconn.ca", "password": "SecurePass789!", "teams": [{"name": "strategy", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "lisa.okonkwo", "email": "lisa.okonkwo@mediconn.ca", "password": "SecurePass321!", "teams": [{"name": "strategy", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "priya.sharma", "message": "Hey team, just wrapped up our Q2 review. We need to start mapping out challenges for our 2026 expansion. Can everyone share their observations?", "create_at": 1688900400000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "daniel.chen", "message": "The B2B sales cycle is killing us. We're averaging 8-12 months to close enterprise deals. That's a major bottleneck if we want aggressive growth by 2026.", "create_at": 1688900700000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "marcus.wright", "message": "Agreed. The multi-stakeholder approval process is brutal. We're dealing with IT, clinical teams, AND administrative decision-makers. Each has different priorities and timelines.", "create_at": 1688901000000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "lisa.okonkwo", "message": "Don't forget compliance. Telehealth regulations keep evolving\u2014what works in BC might need adjustments for Ontario. Staying ahead of regulatory changes is constant work.", "create_at": 1688901300000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "priya.sharma", "message": "Budget constraints are another issue. CFOs want detailed cost justification before signing off. The value proposition needs to be crystal clear.", "create_at": 1688901600000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "daniel.chen", "message": "Legacy system integration has been a nightmare with enterprise clients. The 2022-23 trend shows hospitals and large corporations still running outdated infrastructure. Our platform needs to adapt.", "create_at": 1688901900000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "marcus.wright", "message": "So to summarize: lengthy sales cycles, complex approvals, compliance challenges, budget justification, and legacy integration. That's our roadmap of obstacles.", "create_at": 1688902200000}}
{"type": "post", "post": {"team": "strategy", "channel": "expansion-2026", "user": "priya.sharma", "message": "Exactly. Let's schedule a deep-dive session next week to develop mitigation strategies. I'll send a calendar invite for Tuesday morning.", "create_at": 1688902500000}}

