{"type": "post", "post": {"team": "customer-success", "channel": "crm-systems", "user": "marcus.chen", "message": "We should push for a unified platform. With 1900 employees and our growth trajectory, this fragmentation is only going to get worse.", "create_at": 1740751800000}}
