{"type": "post", "post": {"team": "dealer-operations", "channel": "network-performance", "user": "marcus.chen", "message": "Hey team, quick question - how are we doing on dealer dispute resolution times these days? Got a regional manager asking for benchmarks.", "create_at": 1718888400000}}
