{"type": "post", "post": {"team": "sales-ops", "channel": "dealership-performance", "user": "marcus.chen", "message": "Hey team, just wrapped up the Q1 2025 margin analysis for our dealership network. Got some solid numbers to share.", "create_at": 1712160000000}}
