{"type": "post", "post": {"team": "sales-analytics", "channel": "crm-insights", "user": "marcus.chen", "message": "Hey team, just finished pulling together the Q2 2023 CRM analysis. Found something pretty interesting about our online engagement metrics.", "create_at": 1693753200000}}
