{"type": "post", "post": {"team": "sales-analytics", "channel": "crm-insights", "user": "nina.patel", "message": "Agreed. Marcus, can you put together a deck for the leadership meeting next week? This could really influence our Q4 strategy.", "create_at": 1693755600000}}
