{"type": "user", "user": {"username": "david.martinez", "email": "david.martinez@elexionauto.com", "password": "CyberSec#789!", "first_name": "David", "last_name": "Martinez", "teams": [{"name": "cybersecurity", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "rachel.kim", "email": "rachel.kim@elexionauto.com", "password": "Elexion#2024!", "first_name": "Rachel", "last_name": "Kim", "teams": [{"name": "cybersecurity", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "marcus.chen", "message": "Hey team, just wrapped up the resource allocation review meeting with leadership. Wanted to share some updates on our OTA security focus.", "create_at": 1720612800000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "jennifer.okafor", "message": "Great timing! I've been wondering where we stand with OTA prioritization given the new model launches coming up.", "create_at": 1720613100000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "marcus.chen", "message": "So currently, our cybersecurity team allocates 18% of its efforts to OTA updates. This covers encryption protocols, signature verification, and rollback protection.", "create_at": 1720613400000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "david.martinez", "message": "18% feels low considering how critical OTA is becoming. Especially with the ISO 26262 requirements we need to maintain.", "create_at": 1720613700000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "marcus.chen", "message": "Agreed. That's why leadership approved a significant increase \u2014 we're planning to bump that up to 25% in 2025. The robustness of OTA updates is growing in significance within both cybersecurity and the automotive market overall.", "create_at": 1720614000000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "rachel.kim", "message": "That's a solid jump! Are we looking at additional headcount or redistributing existing resources?", "create_at": 1720614300000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "marcus.chen", "message": "Combination of both. We're hiring two dedicated OTA security engineers and shifting some penetration testing focus toward update mechanisms.", "create_at": 1720614600000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "jennifer.okafor", "message": "Makes sense. Our competitors have had some high-profile OTA vulnerabilities lately. Better to get ahead of this.", "create_at": 1720614900000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "david.martinez", "message": "I'll start drafting the updated threat model for the 2025 roadmap. @rachel.kim can you pull the current attack surface analysis?", "create_at": 1720615200000}}
{"type": "post", "post": {"team": "cybersecurity", "channel": "ota-security", "user": "rachel.kim", "message": "On it. I'll have it ready by EOD tomorrow.", "create_at": 1720615500000}}

