{"type": "post", "post": {"team": "cybersecurity", "channel": "threat-intelligence", "user": "marcus.chen", "message": "Hey team, wanted to touch base on our 2026 threat projections. Have we gotten anything useful from that external market data we purchased last year?", "create_at": 1709726400000}}
