{"type": "post", "post": {"team": "cybersecurity", "channel": "threat-intelligence", "user": "marcus.chen", "message": "Perfect. Let's plan to review next week and make sure our defenses scale accordingly. Thanks everyone!", "create_at": 1709728800000}}

