{"type": "post", "post": {"team": "customer-experience", "channel": "cx-analytics", "user": "marcus.chen", "message": "Hey team, I've been pulling together the Q3 2024 complaint data for the leadership review. Anyone have the breakdown handy?", "create_at": 1738152000000}}
