{"type": "post", "post": {"team": "customer-operations", "channel": "service-analytics", "user": "marcus.chen", "message": "Hey team, just pulled the Q4 2023 service request data from our internal dashboard. Some interesting trends emerging.", "create_at": 1733410800000}}
