{"type": "post", "post": {"team": "compliance", "channel": "carb-zev-program", "user": "marcus.chen", "message": "Team, I've completed the internal audit for our CARB data readiness ahead of the September submission. We have some gaps we need to address.", "create_at": 1692446400000}}
