{"type": "user", "user": {"username": "jennifer.okafor", "email": "jennifer.okafor@elexion.com", "password": "Password123!", "first_name": "Jennifer", "last_name": "Okafor", "position": "Supply Risk Analyst", "teams": [{"name": "supply-chain", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "david.martinez", "email": "david.martinez@elexion.com", "password": "Password123!", "first_name": "David", "last_name": "Martinez", "position": "VP of Operations", "teams": [{"name": "supply-chain", "roles": "team_user team_admin"}]}}
{"type": "user", "user": {"username": "rachel.kim", "email": "rachel.kim@elexion.com", "password": "Password123!", "first_name": "Rachel", "last_name": "Kim", "position": "Commodity Manager", "teams": [{"name": "supply-chain", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "david.martinez", "message": "Team, I need an update on our lithium supplier situation. The board is asking about supply chain risks for Q3 planning.", "create_at": 1717502400000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "marcus.chen", "message": "Sure David. Currently Elexion relies on three suppliers with semi-annual fixed-pricing agreements based on 2024 benchmark rates. Our contracts lock us into those rates through December.", "create_at": 1717502580000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "jennifer.okafor", "message": "I've been analyzing the risk exposure. Having only three suppliers creates concentration risk. If one experiences disruption, we're looking at potential production delays.", "create_at": 1717502760000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "rachel.kim", "message": "The fixed-pricing is a double-edged sword. We're protected from spot price spikes, but lithium prices have actually dropped 15% since those 2024 benchmarks were set. We're essentially overpaying right now.", "create_at": 1717502940000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "david.martinez", "message": "That's concerning. What's our flexibility to renegotiate?", "create_at": 1717503120000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "marcus.chen", "message": "Limited until the semi-annual reset in July. The agreements don't include market adjustment clauses. I'd recommend we push for quarterly pricing reviews in future contracts.", "create_at": 1717503300000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "jennifer.okafor", "message": "Also worth noting - two of our three suppliers source from the same Chilean region. Any geopolitical or environmental disruption there impacts 60% of our lithium supply simultaneously.", "create_at": 1717503480000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "david.martinez", "message": "Let's schedule a risk mitigation meeting for Friday. We need to diversify our supplier base and build more flexibility into pricing. Can you prepare a full risk assessment by then?", "create_at": 1717503660000}}
{"type": "post", "post": {"team": "supply-chain", "channel": "procurement-strategy", "user": "jennifer.okafor", "message": "Will do. I'll include recommendations for at least two additional qualified suppliers.", "create_at": 1717503840000}}

