{"type": "user", "user": {"username": "marcus.chen", "email": "marcus.chen@mediconnsolutions.ca", "password": "Secure#Pass123", "first_name": "Marcus", "last_name": "Chen", "position": "IT Security Manager", "teams": [{"name": "it-security", "roles": "team_admin"}]}}
