{"type": "user", "user": {"username": "david.torres", "email": "david.torres@mediconnsolutions.ca", "password": "Secure#Pass789", "first_name": "David", "last_name": "Torres", "position": "Infrastructure Lead", "teams": [{"name": "it-security", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "linda.wu", "email": "linda.wu@mediconnsolutions.ca", "password": "Secure#Pass321", "first_name": "Linda", "last_name": "Wu", "position": "Compliance Officer", "teams": [{"name": "it-security", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "marcus.chen", "message": "Team, I just got off a call with Elexion Healthcare. They're sharing lessons learned from their AI anomaly detection rollout. We should review before our own implementation.", "create_at": 1686398400000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "priya.sharma", "message": "Good timing! What are they dealing with over there?", "create_at": 1686398520000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "marcus.chen", "message": "Three main issues they're facing: First, excessive false negatives. Minor security breaches went undetected for weeks because the system wasn't flagging them properly.", "create_at": 1686398700000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "david.torres", "message": "Yikes. That's a big deal for healthcare. What else?", "create_at": 1686398820000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "marcus.chen", "message": "Second issue is incompatibility with their existing SIEM platform. They had to bring in costly middleware solutions just to get things talking to each other.", "create_at": 1686398940000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "linda.wu", "message": "We need to verify compatibility with our Splunk setup before we proceed. I'll add this to the vendor checklist.", "create_at": 1686399060000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "marcus.chen", "message": "Third problem: staff resistance and inadequate training. Their team started doing manual overrides that completely bypassed the AI system.", "create_at": 1686399180000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "priya.sharma", "message": "That defeats the entire purpose. We should budget for proper training sessions and get buy-in from the SOC team early.", "create_at": 1686399300000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "david.torres", "message": "Agreed. Let's schedule a meeting with HR to plan a comprehensive training program. June 15th work for everyone?", "create_at": 1686399420000}}
{"type": "post", "post": {"team": "it-security", "channel": "ai-tools-integration", "user": "marcus.chen", "message": "Works for me. I'll document Elexion's challenges in our risk assessment. We can avoid their mistakes if we plan carefully.", "create_at": 1686399540000}}

