{"type": "post", "post": {"team": "infosec", "channel": "security-audits", "user": "david.chen", "message": "Hey team, wanted to share a quick update on the FY2025 internal security audit. We've wrapped up the initial assessment phase.", "create_at": 1735560000000}}
