{"type": "email", "id": "email_001", "subject": "Streamlining IT workflows for Q4", "from": "laura.singh@mediconn.ca", "from_name": "Laura Singh", "to": ["jason.patel@mediconn.ca", "emily.jones@mediconn.ca"], "cc": ["michael.brown@mediconn.ca", "sarah.williams@mediconn.ca", "david.taylor@mediconn.ca"], "date": "2025-09-28 14:30:00", "body": "Dear Team,

