{"type": "user", "user": {"username": "david.chen", "email": "david.chen@leesmarket.ca", "password": "D@vid2023!", "teams": [{"name": "customer-insights", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "priya.sharma", "email": "priya.sharma@leesmarket.ca", "password": "Pr!ya2023!", "teams": [{"name": "customer-insights", "roles": "team_user"}]}}
{"type": "user", "user": {"username": "michael.torres", "email": "michael.torres@leesmarket.ca", "password": "M!chael2023!", "teams": [{"name": "customer-insights", "roles": "team_user"}]}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "karen.wong", "message": "Hey team, I've finished compiling the 2025 quarterly spend analysis for our loyalty members. The generational breakdown is really interesting.", "create_at": 1696761600000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "david.chen", "message": "Great timing! Leadership has been asking about channel preferences by age group. What did you find?", "create_at": 1696762200000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "karen.wong", "message": "Here's the average quarterly spend per loyalty member breakdown:\n\n| Generation | Online | In-Store |\n|---|---|---|\n| Gen Z/Millennials | $195 | $340 |\n| Gen X/Boomers | $145 | $450 |\n\nThe patterns are quite distinct between the groups.", "create_at": 1696762800000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "priya.sharma", "message": "Wow, Gen X/Boomers really dominate in-store spending at $450. That's significantly higher than the younger cohort's $340.", "create_at": 1696763400000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "michael.torres", "message": "But flip side - Gen Z/Millennials spend $195 online versus only $145 for Gen X/Boomers. Makes sense given digital adoption rates.", "create_at": 1696764000000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "david.chen", "message": "This is valuable for our omnichannel strategy. We should probably invest more in enhancing the in-store experience for older demographics while improving our app for younger members.", "create_at": 1696764600000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "karen.wong", "message": "Exactly my thinking. Total spend is actually comparable - younger members at $535 combined vs older at $595. They just prefer different channels.", "create_at": 1696765200000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "priya.sharma", "message": "Should we present this to the marketing team? They're planning the holiday campaigns and this segmentation could help target promotions effectively.", "create_at": 1696765800000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "karen.wong", "message": "Good idea. I'll set up a meeting for next week to share these findings. @michael.torres can you help me build the presentation deck?", "create_at": 1696766400000}}
{"type": "post", "post": {"team": "customer-insights", "channel": "loyalty-analytics", "user": "michael.torres", "message": "On it! I'll have a draft ready by Thursday.", "create_at": 1696767000000}}

